CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS locations(id SERIAL PRIMARY KEY,name TEXT NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS staff_profiles(id SERIAL PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('admin_general','titular','collaborator')),location_id INTEGER REFERENCES locations(id),display_name TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS app_sessions(id BIGSERIAL PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,staff_id INTEGER NOT NULL REFERENCES staff_profiles(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS clients(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),first_name TEXT NOT NULL,last_name TEXT DEFAULT '',dni TEXT DEFAULT '',age INTEGER,phone TEXT DEFAULT '',responsible_full_name TEXT DEFAULT '',responsible_dni TEXT DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sales(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),client_id UUID NOT NULL REFERENCES clients(id),location_id INTEGER NOT NULL REFERENCES locations(id),sale_date DATE NOT NULL DEFAULT CURRENT_DATE,contract_no TEXT DEFAULT '',order_no TEXT DEFAULT '',lens_type TEXT DEFAULT '',frame TEXT DEFAULT '',total NUMERIC(12,2) NOT NULL DEFAULT 0,advance NUMERIC(12,2) NOT NULL DEFAULT 0,balance NUMERIC(12,2) NOT NULL DEFAULT 0,observations TEXT DEFAULT '',created_by TEXT DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),deleted_at TIMESTAMPTZ,lens_price NUMERIC(12,2) DEFAULT 0,frame_price NUMERIC(12,2) DEFAULT 0,other_item TEXT DEFAULT '',other_price NUMERIC(12,2) DEFAULT 0,advance_cash NUMERIC(12,2) DEFAULT 0,advance_yape NUMERIC(12,2) DEFAULT 0);
CREATE TABLE IF NOT EXISTS measurements(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),sale_id UUID NOT NULL UNIQUE REFERENCES sales(id) ON DELETE CASCADE,od_esf TEXT DEFAULT '',od_cil TEXT DEFAULT '',od_eje TEXT DEFAULT '',od_av TEXT DEFAULT '',oi_esf TEXT DEFAULT '',oi_cil TEXT DEFAULT '',oi_eje TEXT DEFAULT '',oi_av TEXT DEFAULT '',add_value TEXT DEFAULT '',dp_dip TEXT DEFAULT '',correction_type TEXT DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),sale_id UUID NOT NULL REFERENCES sales(id),location_id INTEGER NOT NULL REFERENCES locations(id),amount NUMERIC(12,2) NOT NULL,method TEXT NOT NULL DEFAULT 'Efectivo',balance_after NUMERIC(12,2) NOT NULL,created_by TEXT DEFAULT '',paid_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_log(id BIGSERIAL PRIMARY KEY,actor_name TEXT,actor_location_id INTEGER,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,details TEXT,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_sales_location_date ON sales(location_id,sale_date);
CREATE INDEX IF NOT EXISTS idx_clients_dni ON clients(dni);
CREATE INDEX IF NOT EXISTS idx_sales_contract ON sales(contract_no);
INSERT INTO locations(name) VALUES ('MEGAVISION PUNO'),('MEGAVISION CHINCHA'),('MEGAVISION 3') ON CONFLICT(name) DO NOTHING;
